#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────
# Check mode: the non-interactive seam the tests drive.
#
# All of this is authored code below the STAGES marker, so the frozen library
# above stays byte-identical to the wizard template.
# ──────────────────────────────────────────────────────────────────────────

# The one host every question is asked about. A second host is a deliberate
# decision, never a stray string.
GH_HOST="github.com"

# The version floor, in one place. The login flow leans on three things that
# modern releases carry together: the device-code web flow, --skip-ssh-key (so
# an HTTPS login never detours through SSH key setup), and auth status scoped
# to a single host. Raise this constant when the flow leans on something newer;
# never inline a second copy of the number.
GH_MIN_VERSION="2.40.0"

# The documented default proxy, in one place. A machine-local port is exactly
# the kind of value that goes stale, so it lives here, is named in every message
# that uses it, and can be overridden with DSH_GH_PROXY or HTTPS_PROXY without
# editing this file.
GH_PROXY_DEFAULT="http://127.0.0.1:7890"

# How the session reached the host. A closed vocabulary, so the status line
# stays parseable and no branch can invent a new word for the same thing.
PROXY_NONE="none"
PROXY_ENV="env"
PROXY_PERSISTED="persisted"
PROXY_DEFAULT="default"
PROXY_FAILED="failed"

PROXY_KIND="none"
GH_PROXY_URL=""
GH_PROXY_SOURCE=""
GH_PROXY_USED=""
PROBE_OUT=""
PROBE_RC=0
PROBE_UNREACHABLE=0

# The closed set of outcomes. Every judgement lands on exactly one of these and
# on nothing else, so a reader can switch on the state without discovering a new
# string later, and so no branch can invent a second way of saying the same
# thing.
STATE_LOGGED_IN="logged-in"
STATE_GH_MISSING="gh-missing"
STATE_GH_TOO_OLD="gh-too-old"
STATE_UNREACHABLE="host-unreachable"
STATE_NOT_LOGGED_IN="not-logged-in"
STATE_OTHER_ACCOUNT="logged-in-other-account"
STATE_TOKEN_REJECTED="token-rejected"

# Exit codes. Stable, documented in --help, and asserted by the tests. The
# numbers are part of the check-mode contract, not an implementation detail.
EXIT_OK=0
EXIT_USAGE=2
EXIT_GH_MISSING=10
EXIT_GH_TOO_OLD=11
EXIT_HOST_UNREACHABLE=12
EXIT_NOT_LOGGED_IN=13
EXIT_OTHER_ACCOUNT=14
EXIT_TOKEN_REJECTED=15
EXIT_INTERNAL=70

GH_BIN=""
GH_SOURCE=""
GH_VERSION=""
GH_REJECTED=""
GH_USER=""
GH_SCOPES=""
EXPECT_USER=""
JUDGED_STATE=""

# _exit_for_state is the only place that turns a verdict into an exit code. That
# is what keeps every branch on one dispatch path.
_exit_for_state() {
  case "$1" in
    "$STATE_LOGGED_IN")      return "$EXIT_OK" ;;
    "$STATE_GH_MISSING")     return "$EXIT_GH_MISSING" ;;
    "$STATE_GH_TOO_OLD")     return "$EXIT_GH_TOO_OLD" ;;
    "$STATE_UNREACHABLE")    return "$EXIT_HOST_UNREACHABLE" ;;
    "$STATE_NOT_LOGGED_IN")  return "$EXIT_NOT_LOGGED_IN" ;;
    "$STATE_OTHER_ACCOUNT")  return "$EXIT_OTHER_ACCOUNT" ;;
    "$STATE_TOKEN_REJECTED") return "$EXIT_TOKEN_REJECTED" ;;
    *)
      printf 'gh-login-wizard: internal error: unknown state "%s"\n' "$1" >&2
      return "$EXIT_INTERNAL"
      ;;
  esac
}

# _gh runs the resolved CLI with the host pinned, so no call can silently fall
# back to "whatever host this machine happens to default to".
_gh() { GH_HOST="$GH_HOST" "$GH_BIN" "$@"; }

# _gh_version_of BIN prints X.Y.Z from the CLI's version banner, or nothing when
# the banner cannot be parsed. Callers treat nothing as "too old".
_gh_version_of() {
  local out
  out=$("$1" --version 2>/dev/null | head -n1) || return 0
  printf '%s' "$out" \
    | sed -n 's/.*[Vv]ersion[[:space:]]\{1,\}\([0-9][0-9]*\.[0-9][0-9]*\.[0-9][0-9]*\).*/\1/p'
}

# _version_ge ACTUAL MINIMUM succeeds when ACTUAL is at least MINIMUM.
_version_ge() {
  local -a a b
  local i
  IFS=. read -r -a a <<<"$1"
  IFS=. read -r -a b <<<"$2"
  for i in 0 1 2; do
    if (( ${a[i]:-0} > ${b[i]:-0} )); then return 0; fi
    if (( ${a[i]:-0} < ${b[i]:-0} )); then return 1; fi
  done
  return 0
}

# _gh_candidates prints conventional install locations, most likely first, so a
# CLI installed outside PATH is still found. Absolute on purpose: these are
# fallbacks for "not on PATH", not a second PATH search.
_gh_candidates() {
  local os
  os=$(uname -s 2>/dev/null) || os=unknown
  case "$os" in
    MINGW*|MSYS*|CYGWIN*)
      printf '%s\n' "/c/Program Files/GitHub CLI/gh.exe"
      if [[ -n "${LOCALAPPDATA:-}" ]]; then
        printf '%s\n' "$LOCALAPPDATA/GitHubCLI/gh.exe" \
          "$LOCALAPPDATA/Microsoft/WinGet/Links/gh.exe"
      fi
      if [[ -n "${HOME:-}" ]]; then
        printf '%s\n' "$HOME/scoop/shims/gh.exe"
      fi
      ;;
    Darwin)
      printf '%s\n' /opt/homebrew/bin/gh /usr/local/bin/gh
      if [[ -n "${HOME:-}" ]]; then printf '%s\n' "$HOME/.local/bin/gh"; fi
      ;;
    *)
      printf '%s\n' /usr/bin/gh /usr/local/bin/gh /snap/bin/gh \
        /home/linuxbrew/.linuxbrew/bin/gh
      if [[ -n "${HOME:-}" ]]; then printf '%s\n' "$HOME/.local/bin/gh"; fi
      ;;
  esac
}

# _resolve_gh finds the CLI and records how it was found. Order: the explicit
# environment variable, then PATH, then conventional locations. The first
# usable hit wins and the caller can say which one won. A set-but-unusable
# environment variable is recorded in GH_REJECTED instead of being swallowed,
# so it can be named in the diagnostic. Succeeds when found.
_resolve_gh() {
  GH_BIN=""
  GH_SOURCE=""
  GH_REJECTED=""
  local cand=""

  if [[ -n "${DSH_GH_PATH:-}" ]]; then
    if [[ -f "$DSH_GH_PATH" && -x "$DSH_GH_PATH" ]]; then
      GH_BIN="$DSH_GH_PATH"
      GH_SOURCE="env:DSH_GH_PATH"
      return 0
    fi
    GH_REJECTED="DSH_GH_PATH=$DSH_GH_PATH (not an executable file)"
  fi

  cand=$(command -v gh 2>/dev/null) || cand=""
  if [[ -n "$cand" ]]; then
    GH_BIN="$cand"
    GH_SOURCE="path"
    return 0
  fi

  while IFS= read -r cand; do
    if [[ -n "$cand" && -f "$cand" && -x "$cand" ]]; then
      GH_BIN="$cand"
      GH_SOURCE="located"
      return 0
    fi
  done < <(_gh_candidates)

  return 1
}

# _has_credential asks whether *some* credential is stored for the host. It says
# nothing about whether that credential is still any good — that is the API's
# job, and keeping those two questions apart is the whole point of this file.
_has_credential() {
  _gh auth token --hostname "$GH_HOST" >/dev/null 2>&1
}

# _read_scopes reports the token's scopes for diagnosis only. The parser is
# deliberately forgiving: if the CLI's wording changes this goes empty and the
# verdict is unaffected, because nothing here is allowed to gate anything.
_read_scopes() {
  local line=""
  line=$(_gh auth status --hostname "$GH_HOST" 2>/dev/null \
    | sed -n 's/.*[Tt]oken scopes:[[:space:]]*//p' | sed -n '1p') || line=""
  [[ -n "$line" ]] || return 0
  printf '%s' "$line" | tr -d "'" | tr -s ' ' | sed 's/^ //; s/ $//; s/, /,/g'
}

# _classify_api_failure turns a failed authenticated call into either a network
# problem or a credential problem. It is a heuristic over the CLI's own error
# text, kept in one place so the proxy work can replace it with a real
# reachability probe without touching the judgement above it.
_classify_api_failure() {
  case "$1" in
    *"dial tcp"*|*"no such host"*|*"could not resolve"*|*"i/o timeout"*|*"Timeout"*|\
    *"connection refused"*|*"connection reset"*|*"network is unreachable"*|\
    *"TLS handshake"*|*"proxyconnect"*|*"context deadline exceeded"*|\
    *"temporary failure in name resolution"*|*"no route to host"*)
      printf 'unreachable' ;;
    *) printf 'credentials' ;;
  esac
}

# _gh_direct runs the CLI with the proxy variables cleared, so the direct attempt
# is genuinely direct even on a machine whose shell exports a proxy.
_gh_direct() {
  GH_HOST="$GH_HOST" HTTPS_PROXY= https_proxy= HTTP_PROXY= http_proxy= \
    ALL_PROXY= all_proxy= "$GH_BIN" "$@"
}

# _gh_via_proxy runs the CLI through one explicit proxy.
_gh_via_proxy() {
  local url="$1"
  shift
  GH_HOST="$GH_HOST" HTTPS_PROXY="$url" https_proxy="$url" \
    HTTP_PROXY="$url" http_proxy="$url" "$GH_BIN" "$@"
}

# _proxy_candidate picks the proxy to try when the direct attempt never got an
# answer, in the order of how much the user already committed to it: the
# environment they set up, then a proxy an earlier run recorded, then the
# documented default. It sets GH_PROXY_URL and GH_PROXY_SOURCE instead of
# printing them, because a command substitution would lose the assignments with
# its subshell — and the source is what every message has to name.
_proxy_candidate() {
  local url=""
  GH_PROXY_URL=""
  GH_PROXY_SOURCE=""

  url="${HTTPS_PROXY:-${https_proxy:-${HTTP_PROXY:-${http_proxy:-}}}}"
  if [[ -n "$url" ]]; then
    GH_PROXY_URL="$url"; GH_PROXY_SOURCE="$PROXY_ENV"; return 0
  fi

  url=$(_existing DSH_GH_PROXY) || url=""
  if [[ -n "$url" ]]; then
    GH_PROXY_URL="$url"; GH_PROXY_SOURCE="$PROXY_PERSISTED"; return 0
  fi

  if [[ -n "$GH_PROXY_DEFAULT" ]]; then
    GH_PROXY_URL="$GH_PROXY_DEFAULT"; GH_PROXY_SOURCE="$PROXY_DEFAULT"; return 0
  fi

  return 1
}

# _reachable [PROXY] answers one question: did anything answer on the other end.
# curl is used because it asks the network without needing a credential — the
# CLI itself refuses locally when nobody is logged in, which would make a dead
# network and a missing login look identical, and that distinction is the whole
# point of this file. A 4xx counts as an answer: reachable, and saying no.
_reachable() {
  local proxy="${1:-}"
  if command -v curl >/dev/null 2>&1; then
    if [[ -n "$proxy" ]]; then
      curl -sS -m 8 -o /dev/null -x "$proxy" "https://$GH_HOST" 2>/dev/null
    else
      curl -sS -m 8 -o /dev/null "https://$GH_HOST" 2>/dev/null
    fi
    return
  fi
  # No curl. Fall back to the CLI, which is the weaker answer: it cannot tell a
  # missing login from a dead network when it refuses before dialling. Say so
  # here rather than pretending the two probes are equivalent.
  if [[ -n "$proxy" ]]; then
    _gh_via_proxy "$proxy" api user >/dev/null 2>&1
  else
    _gh_direct api user >/dev/null 2>&1
  fi
}

# _probe_session decides whether the host can be reached and, if only a proxy
# gets there, which proxy that was. Only then does it ask the authenticated
# question. It leaves PROBE_RC, PROBE_OUT, PROBE_UNREACHABLE, PROXY_KIND and
# GH_PROXY_USED for the caller, which is the only place a verdict is drawn.
# _attempt_session [PROXY] makes one honest attempt: probe the route, and if
# anything answers, ask the authenticated question through it. It succeeds when
# the host gave a non-transport answer — a 401 counts, because the host spoke.
# Everything else, including "curl says fine but the CLI cannot connect", is a
# failure and lets the caller try the next route.
_attempt_session() {
  local proxy="${1:-}"

  if ! _reachable "$proxy"; then return 1; fi

  PROBE_RC=0
  if [[ -n "$proxy" ]]; then
    PROBE_OUT=$(_gh_via_proxy "$proxy" api user --jq .login 2>&1) || PROBE_RC=$?
  else
    PROBE_OUT=$(_gh_direct api user --jq .login 2>&1) || PROBE_RC=$?
  fi

  if (( PROBE_RC != 0 )) && [[ "$(_classify_api_failure "$PROBE_OUT")" == "unreachable" ]]; then
    return 1
  fi
  return 0
}

# _probe_session decides whether the host can be reached and, if only a proxy
# gets there, which proxy that was. Direct is tried first, always; a proxy is
# consulted only after the direct route produced no answer at all. It leaves
# PROBE_RC, PROBE_OUT, PROBE_UNREACHABLE, PROXY_KIND and GH_PROXY_USED for the
# caller, which is the only place a verdict is drawn.
_probe_session() {
  PROBE_OUT=""
  PROBE_RC=0
  PROBE_UNREACHABLE=0
  PROXY_KIND="$PROXY_NONE"
  GH_PROXY_USED=""
  GH_PROXY_SOURCE=""

  if _attempt_session; then return 0; fi

  if _proxy_candidate && _attempt_session "$GH_PROXY_URL"; then
    PROXY_KIND="$GH_PROXY_SOURCE"
    GH_PROXY_USED="$GH_PROXY_URL"
    return 0
  fi

  GH_PROXY_USED="$GH_PROXY_URL"
  PROXY_KIND="$PROXY_FAILED"
  PROBE_UNREACHABLE=1
  return 0
}

# _judge decides the verdict and leaves it in JUDGED_STATE. It is called, not
# run inside a command substitution: its other job is to fill in the globals the
# status line reports, and those would die with the subshell.
_judge() {
  GH_USER=""
  GH_SCOPES=""

  if ! _resolve_gh; then
    if [[ -n "$GH_REJECTED" ]]; then
      printf 'gh-login-wizard: no usable gh. %s; nothing on PATH or in the usual install locations either.\n' "$GH_REJECTED" >&2
    else
      printf 'gh-login-wizard: no usable gh on PATH or in the usual install locations.\n' >&2
    fi
    printf '  install https://cli.github.com, or point DSH_GH_PATH at the executable\n' >&2
    JUDGED_STATE="$STATE_GH_MISSING"
    return 0
  fi

  GH_VERSION=$(_gh_version_of "$GH_BIN")

  if [[ -z "$GH_VERSION" ]]; then
    printf 'gh-login-wizard: %s did not report a parseable version; treating it as too old.\n' "$GH_BIN" >&2
    JUDGED_STATE="$STATE_GH_TOO_OLD"
    return 0
  fi

  if ! _version_ge "$GH_VERSION" "$GH_MIN_VERSION"; then
    printf 'gh-login-wizard: gh %s is older than the required %s (found via %s).\n' \
      "$GH_VERSION" "$GH_MIN_VERSION" "$GH_SOURCE" >&2
    printf '  upgrade from https://cli.github.com\n' >&2
    JUDGED_STATE="$STATE_GH_TOO_OLD"
    return 0
  fi

  if [[ -n "$GH_REJECTED" ]]; then
    printf 'gh-login-wizard: warning: %s was rejected; using %s (via %s).\n' \
      "$GH_REJECTED" "$GH_BIN" "$GH_SOURCE" >&2
  fi

  # Reachability first, then credentials. A proxy is consulted only when the
  # direct attempt produced no answer at all — never because a token was
  # refused, which retrying through a proxy could not fix.
  _probe_session

  if (( PROBE_UNREACHABLE )); then
    if [[ -n "$GH_PROXY_USED" ]]; then
      printf 'gh-login-wizard: %s answered neither directly nor through the proxy %s.\n' "$GH_HOST" "$GH_PROXY_USED" >&2
      printf '  that proxy came from %s; override it with HTTPS_PROXY=... or DSH_GH_PROXY=...\n' "$GH_PROXY_SOURCE" >&2
    else
      printf 'gh-login-wizard: %s never answered, and no proxy was available to try.\n' "$GH_HOST" >&2
      printf '  set HTTPS_PROXY or DSH_GH_PROXY if this machine needs one\n' >&2
    fi
    printf '  fix connectivity first; re-authenticating will not help\n' >&2
    JUDGED_STATE="$STATE_UNREACHABLE"
    return 0
  fi

  if (( PROBE_RC == 0 )); then
    GH_USER=$(printf '%s\n' "$PROBE_OUT" | grep -Ex '[A-Za-z0-9-]+' | sed -n '1p') || GH_USER=""
    if [[ -z "$GH_USER" ]]; then
      printf 'gh-login-wizard: the authenticated call succeeded but named no account; refusing to call that a usable session.\n' >&2
      JUDGED_STATE="$STATE_TOKEN_REJECTED"
      return 0
    fi
    GH_SCOPES=$(_read_scopes)
    if [[ -n "$EXPECT_USER" && "$GH_USER" != "$EXPECT_USER" ]]; then
      printf 'gh-login-wizard: signed in as %s, but %s was expected.\n' "$GH_USER" "$EXPECT_USER" >&2
      printf '  switch with: gh auth switch --hostname %s --user %s\n' "$GH_HOST" "$EXPECT_USER" >&2
      JUDGED_STATE="$STATE_OTHER_ACCOUNT"
      return 0
    fi
    JUDGED_STATE="$STATE_LOGGED_IN"
    return 0
  fi

  if _has_credential; then
    printf 'gh-login-wizard: a credential is stored for %s, but %s refused it.\n' "$GH_HOST" "$GH_HOST" >&2
    printf '  re-authenticate with: gh auth login --hostname %s --git-protocol https --web\n' "$GH_HOST" >&2
    JUDGED_STATE="$STATE_TOKEN_REJECTED"
    return 0
  fi

  printf 'gh-login-wizard: no credential is stored for %s.\n' "$GH_HOST" >&2
  printf '  log in with: gh auth login --hostname %s --git-protocol https --web\n' "$GH_HOST" >&2
  JUDGED_STATE="$STATE_NOT_LOGGED_IN"
  return 0
}

# _emit_status prints the single machine-readable line. Fixed field order,
# empty values where unknown, so a reader splits on spaces once and never
# parses prose. Human diagnostics must go to stderr instead.
_emit_status() {
  printf 'state=%s exe=%s version=%s source=%s host=%s minimum=%s user=%s scopes=%s proxy=%s\n' \
    "$1" "${GH_BIN:-}" "${GH_VERSION:-}" "${GH_SOURCE:-none}" \
    "$GH_HOST" "$GH_MIN_VERSION" "${GH_USER:-}" "${GH_SCOPES:-}" "${PROXY_KIND:-none}"
}

# check_mode is the seam: it never reads stdin, never prompts, never opens a
# browser, and writes nothing. Exit code says what happened, stdout carries the
# one status line, stderr says why a human should care.
check_mode() {
  EXPECT_USER=""
  while (( $# )); do
    case "$1" in
      --expect-user)
        shift
        if (( $# == 0 )); then
          printf 'gh-login-wizard: --expect-user needs an account name\n' >&2
          return "$EXIT_USAGE"
        fi
        EXPECT_USER="$1"
        shift
        ;;
      --expect-user=*) EXPECT_USER="${1#*=}"; shift ;;
      *)
        printf 'gh-login-wizard: unexpected argument: %s\n' "$1" >&2
        return "$EXIT_USAGE"
        ;;
    esac
  done

  _judge
  _emit_status "$JUDGED_STATE"
  _exit_for_state "$JUDGED_STATE"
}

usage() {
  cat <<'USAGE'
gh-login-wizard.sh — 让你本机的 GitHub CLI 处于可用的登录状态

用法:
  gh-login-wizard.sh                     交互式走完登录流程（默认）
  gh-login-wizard.sh --check             非交互检查，不提示、不开浏览器、不写盘
  gh-login-wizard.sh --check --expect-user octocat
                                         还要求当前登录的正是这个账号
  gh-login-wizard.sh --help              显示本说明

--check 做什么:
  找到 gh → 判断版本 → 用一次真实认证请求判断这个主机能不能用。
  只问 github.com 一个主机，别的 host 的凭据坏掉不影响结论。
  stdout 恰好一行，空格分隔的 key=value，字段顺序固定:
    state  exe  version  source  host  minimum  user  scopes  proxy
  人类可读的原因一律走 stderr，所以 stdout 可以直接切分。

state 取值（闭集，不会有别的）:
  logged-in                可用，user 是当前账号
  gh-missing               找不到 gh
  gh-too-old               版本过旧，或版本号无法解析
  host-unreachable         主机没有应答（网络问题，不是登录问题）
  not-logged-in            这个主机上没有存凭据
  logged-in-other-account  有凭据且能用，但不是 --expect-user 要的账号
  token-rejected           存了凭据，但被主机拒绝

proxy 取值（闭集）:
  none        直连就能通
  env         只有走环境里的 HTTPS_PROXY / HTTP_PROXY 才通
  persisted   只有走之前记录进 .env 的 DSH_GH_PROXY 才通
  default     只有走脚本里的文档化默认值才通
  failed      直连和代理都不通（stderr 会点名试过哪个地址）

退出码:
  0    可用
  2    参数错误
  10   找不到 gh
  11   gh 版本过旧，或版本号无法解析
  12   主机不可达
  13   没有登录
  14   登录的不是期望的账号
  15   凭据被拒绝
  70   内部错误（未知状态）
USAGE
}

# ──────────────────────────────────────────────────────────────────────────
# The human flow: a presenter over the verdict.
#
# Nothing here decides anything. It asks _judge — the same judgement check mode
# uses — and then says, in the operator's language, what that verdict means for
# the person at the terminal. A fix in the judgement therefore cannot leave the
# wizard telling a different story from --check.
# ──────────────────────────────────────────────────────────────────────────

# _title opens a one-stage run without the library banner's "Ready to start?"
# prompt, which is pure noise when the answer is already "nothing to do".
_title() {
  printf '\n%s%s  %s%s\n\n' "$BOLD" "$BLUE" "$1" "$RESET"
}

# _pause is the library's pause with one difference: end-of-input is not the
# same as pressing Enter. A wizard that walks on after the terminal closes has
# failed at the only thing it exists for.
_pause() {
  printf '  %s%s%s ' "$DIM" "${1:-按 Enter 继续}" "$RESET"
  local line=""
  if ! IFS= read -r line; then
    printf '\n'
    _no_input
  fi
}

# _no_input is the single answer to "nobody is there to press Enter". It covers
# both a terminal that closed mid-flow and a run whose input was redirected,
# and it always says how to get further instead of leaving the operator stuck.
_no_input() {
  warn "读不到输入：授权未完成，重跑本脚本即可再试一次"
  say "通过管道或重定向运行的，Windows 的 Git Bash 里用: winpty bash $0"
  say "只想确认状态而不交互: $0 --check"
  exit 130
}

# _interrupted is what Ctrl-C means here: not completed, try again. Never a
# trace and never a half-written summary.
_interrupted() {
  printf '\n'
  warn "已中断：授权未完成，重跑本脚本即可再试一次"
  exit 130
}

# _proxy_words renders the closed proxy vocabulary for a human.
_proxy_words() {
  case "$PROXY_KIND" in
    "$PROXY_NONE")      printf '不需要' ;;
    "$PROXY_ENV")       printf '%s（来自环境变量）' "$GH_PROXY_USED" ;;
    "$PROXY_PERSISTED") printf '%s（之前记录的）' "$GH_PROXY_USED" ;;
    "$PROXY_DEFAULT")   printf '%s（默认值）' "$GH_PROXY_USED" ;;
    *)                  printf '不可用' ;;
  esac
}

# _summary always answers the same five questions. A summary that cannot name an
# account is not a success summary, so it is never printed as one.
_summary() {
  printf '\n'
  note "主机:      $GH_HOST"
  note "账号:      ${GH_USER:-未确认}"
  note "协议:      https"
  note "代理:      $(_proxy_words)"
  if (( ${#WRITTEN_ENV[@]} )); then
    note "写入文件:  $ENV_FILE ${WRITTEN_ENV[*]}"
  else
    note "写入文件:  无"
  fi
}

# _explain_blocked says, in the script's own voice, why nothing can proceed.
# The technical reason already went to stderr from the judgement.
_explain_blocked() {
  case "$JUDGED_STATE" in
    "$STATE_GH_MISSING")
      say "找不到 gh 可执行文件。"
      say "装好后重跑本脚本，或设 DSH_GH_PATH 指向它的可执行文件。"
      ;;
    "$STATE_GH_TOO_OLD")
      say "gh 版本低于 $GH_MIN_VERSION。"
      say "升级后重跑：https://cli.github.com"
      ;;
    "$STATE_UNREACHABLE")
      say "$GH_HOST 没有应答。"
      say "先解决网络或代理，再重跑本脚本。重新登录解决不了这个问题。"
      ;;
  esac
}

_interactive() {
  # There is deliberately no upfront "is this a terminal?" gate. The hazard is
  # not the absence of a TTY, it is walking on after the input has gone — so
  # every prompt reports at the moment it cannot read, through _no_input. That
  # also keeps the flow drivable from a pipe, which is how it gets verified.

  # Ctrl-C must read as "not completed", never as a mysterious death.
  trap '_interrupted' INT TERM

  # One judgement, shared with --check. Everything below only renders it.
  _judge

  case "$JUDGED_STATE" in
    "$STATE_GH_MISSING"|"$STATE_GH_TOO_OLD"|"$STATE_UNREACHABLE")
      TOTAL_STAGES=1
      _title "GitHub CLI 登录"
      stage "前置检查 · 现在做不到"
      _explain_blocked
      return 1
      ;;

    "$STATE_LOGGED_IN")
      TOTAL_STAGES=1
      _title "GitHub CLI 登录"
      stage "检查 · 已经可用"
      say "已经是登录状态，不需要重复登录。"
      note "可执行文件：$GH_BIN"
      note "版本：$GH_VERSION"
      if confirm "要改用另一个账号吗？"; then
        local wanted=""
        ask wanted "输入要切换到的账号名"
        if [[ -n "$wanted" ]]; then
          _gh auth switch --hostname "$GH_HOST" --user "$wanted" \
            || warn "切换没有成功，当前仍是 $GH_USER"
          _judge
        fi
      fi
      # finish() clears the screen as its first act, so the summary has to come
      # after it or the human never sees it. The tests never noticed: a captured
      # stdout still contains text that was scrolled off a terminal.
      finish
      _summary
      return 0
      ;;

    *)
      # not-logged-in or token-rejected: the only path that runs a login.
      TOTAL_STAGES=3
      banner "GitHub CLI 登录"

      stage "当前状态 · 需要登录"
      case "$JUDGED_STATE" in
        "$STATE_NOT_LOGGED_IN") say "这台机器还没有为 $GH_HOST 存过凭据。" ;;
        "$STATE_TOKEN_REJECTED") say "存过凭据，但 $GH_HOST 拒绝了它。" ;;
      esac
      note "可执行文件：$GH_BIN"
      note "版本：$GH_VERSION"
      _pause "按 Enter 继续"

      stage "设备码登录 · 浏览器授权"
      case "$PROXY_KIND" in
        "$PROXY_NONE")
          note "$GH_HOST 直连正常，本次不需要代理"
          ;;
        "$PROXY_FAILED")
          if [[ -n "$GH_PROXY_USED" ]]; then
            warn "直连不通，代理 $GH_PROXY_USED 也不通"
          else
            warn "直连不通，也没有可试的代理"
          fi
          warn "把 HTTPS_PROXY 或 DSH_GH_PROXY 指对后重跑本脚本"
          _pause "按 Enter 仍然试一次"
          ;;
        *)
          export HTTPS_PROXY="$GH_PROXY_USED" HTTP_PROXY="$GH_PROXY_USED"
          export https_proxy="$GH_PROXY_USED" http_proxy="$GH_PROXY_USED"
          write_env DSH_GH_PROXY "$GH_PROXY_USED"
          note "直连不通，本次走代理 $GH_PROXY_USED（来源：$PROXY_KIND）"
          note "已记入 $ENV_FILE；新开的 shell 先执行: export HTTPS_PROXY='$GH_PROXY_USED'"
          ;;
      esac

      step "接下来 gh 会打印一次性验证码"
      step "在页面粘贴验证码 → Continue → Authorize GitHub CLI"
      step "协议选 HTTPS，SSH 密钥问题会被跳过"
      open_url "https://github.com/login/device"
      _pause "准备好在浏览器里操作后，按 Enter 启动 gh auth login"

      _gh auth login --hostname "$GH_HOST" --git-protocol https --web --skip-ssh-key \
        || warn "gh auth login 未正常结束（可能取消、超时或网络中断）"

      stage "验证 · 真实调用"
      _judge
      if [[ "$JUDGED_STATE" == "$STATE_LOGGED_IN" && -n "$GH_USER" ]]; then
        say "已验证：$GH_USER @ $GH_HOST"
        finish
        _summary
        return 0
      fi
      warn "仍未完成：$JUDGED_STATE"
      _explain_blocked
      say "重跑本脚本即可再试一次。"
      return 1
      ;;
  esac
}

run_wizard() {

# ── Entry dispatch ────────────────────────────────────────────────────────
# --check is the non-interactive seam; everything else is the human flow.
# Dispatching here keeps the template's last line untouched.
local rc=0
case "${1:-}" in
  --check)   shift; check_mode "$@" || rc=$?; return "$rc" ;;
  --help|-h) usage; return "$EXIT_OK" ;;
  --*)       printf 'unknown option: %s\n\n' "$1" >&2; usage >&2; return "$EXIT_USAGE" ;;
esac

_interactive
}

run_wizard "$@"; exit